def polish(html,page=''):
    html=re.sub(r'<body([^>]*)>',lambda m:'<body'+(re.sub(r'class="([^"]*)"',lambda c:'class="'+c[1]+' spatial-ui"',m[1]) if 'class="' in m[1] else m[1]+' class="spatial-ui"')+'>',html,count=1)
    if page=='home':html=re.sub(r'<footer class="site-footer wrap">.*?</footer>',lambda m:FOOTER,html,flags=re.S)
    if page in TOOLS:html=html.replace('</main>',TOOLS[page]+'</main>')
    html=re.sub(r'>\s*VOICEGUARD(?=<)', '><span class="brand-voice">VOICE</span><span class="brand-guard">GUARD</span>',html)
    html=re.sub(r'<link rel="preload"[^>]*manrope-latin\.woff2[^>]*>', '', html)
    html=html.replace('</head>','<link rel="preload" href="/assets/plus-jakarta-sans-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/presentation.css?v=4"><link rel="stylesheet" href="/assets/spatial.css?v=2"><link rel="stylesheet" href="/assets/responsive.css?v=4"></head>')
    return html.replace('</body>','<script src="/assets/presentation.js?v=4" defer></script><script src="/assets/spatial.js?v=2" defer></script></body>')
